{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide with a very high assay-transfer score, has oral bioavailability ≤3% in patients, directly supporting low F for the query's sulfated saccharide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Zanamivir, a polar N-acetyl sugar acid, has an absolute oral bioavailability of 2% in healthy volunteers, providing strong direct evidence that the query's carbohydrate-acid structure is associated with F < 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Acamprosate, an N-acetyl sulfonate, has an absolute oral bioavailability of 11 ± 1% in healthy male volunteers, below the 20% threshold and supportive of low F for the query's ionized polar motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C24"],
      "claim": "N-acetylcysteine, containing the N-acetyl carboxylic acid fragment, shows oral bioavailability of about 10% in healthy subjects, supporting low F for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Glucoraphanin, a sulfate-containing glycoside, has oral bioavailability of only 5% (range 1–45%) in humans, supporting low F for the query's sulfated sugar framework.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "One record for N-acetylcysteine reports oral bioavailability around 80% in humans, which is contradictory to the low-F pattern, but it is an outlier against multiple consistent absolute and comparative low-bioavailability measurements.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues—highly polar, ionized saccharides, sulfonates, and N-acetyl acids—show low oral bioavailability (≤3%, 2%, 4%, 5%, 11%) in humans. The query's multiple ionizable groups, high polarity, and carbohydrate-acid/sulfate character strongly predict F < 20%.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule; all evidence comes from close analogues.",
    "One contradictory N-acetylcysteine record (C04) reporting ~80% bioavailability is not mechanistically reconciled, but it is outweighed by numerous consistent low-F measurements."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

